class ToolPipeline:
    """守卫工具执行管道。

    用法：
        pipeline = ToolPipeline(dispatch_fn)
        pipeline.add_pre_hook(approval_guard)
        pipeline.add_pre_hook(sandbox_check)
        pipeline.add_post_hook(result_logger)
        pipeline.add_post_hook(output_trimmer)

        result = await pipeline.execute(ToolCall(name='shell_exec', args={...}))
    """

    def __init__(self, dispatch_fn: Callable = None,
                 default_timeout_ms: int = 30_000,
                 max_parallel: int = 5):
        """
        Args:
            dispatch_fn: 实际的工具调用分发函数 (name, args) -> Any
            default_timeout_ms: 默认超时（毫秒）
            max_parallel: 并行工具调用上限
        """
        self._dispatch_fn = dispatch_fn
        self._default_timeout_ms = default_timeout_ms
        self._max_parallel = max_parallel
        self._pre_hooks: list[PreHook] = []
        self._post_hooks: list[PostHook] = []
        self._semaphore: Optional[asyncio.Semaphore] = None

    @property
    def semaphore(self) -> asyncio.Semaphore:
        """延迟创建 semaphore（需要在事件循环内）。"""
