def make_output_limit_hook(limit: int = 4000) -> PostHook:
    """创建输出裁剪钩子。"""
    def _hook(call: ToolCall, result: ToolResult) -> ToolResult:
        if result.data and isinstance(result.data, str):
            if len(result.data) > limit:
                result.data = result.data[:limit] + '...(truncated)'
        return result
    return _hook


def make_call_logger() -> PostHook:
    """创建调用日志钩子。"""
    def _hook(call: ToolCall, result: ToolResult) -> ToolResult:
        status = 'ok' if result.success else ('timeout' if result.timed_out
                                               else 'error')
        logger.info('[ToolPipeline] %s(%s) -> %s %.0fms',
                    call.name, call.call_id, status, result.duration_ms)
        return result
    return _hook


def make_sandbox_deny_hook(denied_tools: list = None) -> PreHook:
    """创建沙箱拒绝钩子（禁止特定工具）。"""
    denied = set(denied_tools or [])
    def _hook(call: ToolCall) -> Optional[str]:
        if call.name in denied:
            return '工具 %s 已被沙箱策略禁止' % call.name
        return None
    return _hook
